"""Model-owned task assessment, separate from external scientific evaluation."""
from copy import deepcopy
STATUSES = ('achieved', 'conditional_conflict', 'unresolved')
CONTINUATION_GUIDANCE = " Before stopping unresolved, assess next_step against available materials,\ntools, evidence and constraints. Perform authorized feasible work with scientific grounds to advance\nthe goal. Otherwise identify missing input, a binding constraint or why available work lacks decision\nvalue. A selected method's failure alone is not a blocker; a supported requirement conflict permits\nimmediate clarification. No exhaustive search, identical repetition, guaranteed success or unsafe\ncontinuation is required. State what possible outcomes would change the next decision."
GUIDANCE = ' Goal status: achieved needs qualifying evidence; conditional_conflict needs incompatible\nrequirements under an applicable model; unresolved retains missing information. Labels are not grades.\nIn decision_basis.working_model state assumptions, applicability from relevant priors and contrary\nevidence, and constraint implications. Conditional knowledge is usable; limitations alone are not\ncounterevidence. Do not invent applicability for a preferred conclusion. Genuine uncertainty can remain\nunresolved; failed trials alone do not establish a conflict. Use decision_ref or explicitly supersedes\non revision; record_plan shares this record. Achieved reports need no dilemma. Predictor independently\nassesses applicability, implications and stopping through decision_assessment bound to decision_subject_id.\nHonest reporting need not resolve the task. Dispose advice with reasons; it cannot force continuation.'
QUALITY_GUIDANCE = ' Applicable public quality criteria bind achieved claims. Accurate reporting of\nfailure does not satisfy them; meeting one does not waive another. Identify the complete clause,\nconditions and exceptions behind each material requirement claim. Separate requirements from design\npreferences; neither invent nor relax them. Endpoint requirement_context snapshots public declarations\nat calculation time, not applicability or a verdict. Reconcile changed declarations. If requirements\nremain unmet, assess supported continuation or a justified unresolved/conditional-conflict conclusion.\nWhen changing methods, reassess the adopted observations. A shared acquisition timestamp need not\nmean equal reaction/exposure ages; reconcile ages and other material condition differences.\nPredictor assesses requirement satisfaction separately from numeric accuracy. These are scientific\nassessments, not grades or prescribed recovery.'
GUIDANCE += QUALITY_GUIDANCE + CONTINUATION_GUIDANCE

def resolution_schema():
    return {'type': 'object', 'properties': {'status': {'type': 'string', 'enum': list(STATUSES)}, 'basis': {'type': 'string', 'description': 'Public evidence, applicable assumptions and why they support this task status.'}, 'next_step': {'type': 'string', 'description': 'Remaining question, needed clarification or informative next step; explain why none is needed if achieved.'}}, 'required': ['status', 'basis', 'next_step'], 'additionalProperties': False}

def read_resolution(arguments):
    if 'task_resolution' not in arguments:
        return {'status': 'unassessed', 'basis': 'No explicit task assessment was supplied.', 'next_step': 'Task resolution has not been assessed.'}
    value = arguments['task_resolution']
    if not isinstance(value, dict) or set(value) != {'status', 'basis', 'next_step'} or value.get('status') not in STATUSES or any((not isinstance(value.get(k), str) or not value[k].strip() for k in ('basis', 'next_step'))):
        raise ValueError('task_resolution requires a valid status, basis and next_step')
    return deepcopy(value)
